class UnknownOperationError(OFAuthError, ValueError):
    """An operation name that is not in `OPERATION_SCOPES`."""


def _canonical(operation: str) -> str:
    if operation in OPERATION_SCOPES:
        return operation
    # Accept the Python spelling too: "vault_plus.get_stats" -> "vaultPlus.getStats".
    camel = re.sub(r"_([a-z0-9])", lambda m: m.group(1).upper(), operation)
    if camel in OPERATION_SCOPES:
        return camel
    raise UnknownOperationError(f"Unknown operation: {operation!r}")


def scope_for(operation: str) -> Scope | None:
    """The scope one operation needs (None when it needs none). Raises `UnknownOperationError`."""
    return OPERATION_SCOPES[_canonical(operation)]


def scopes_for(*operations: str) -> list[str]:
    """The sorted, de-duplicated scopes needed to call `operations`.

    Names are canonical (`"access.chats.messages.send"`); the snake_case spelling
    (`"vault_plus.get_stats"`) works too. Unknown names raise `UnknownOperationError`.
    """
    scopes = {scope for scope in (scope_for(op) for op in operations) if scope}
    return sorted(scopes)
